void HalogenServer::load(const std::string& model_name, const ModelInfo& model_info,
                         const RecipeOptions& options, bool do_not_upgrade) {
    (void)do_not_upgrade;  // install_backend() is a no-op once the pinned image is present
    backend_manager_->install_backend(halogen::descriptor.recipe, kBackend);

    const std::string checkpoint = model_info.resolved_path("main");
    if (checkpoint.empty() || !fs::exists(checkpoint)) {
        throw std::runtime_error("halogen: HGN checkpoint not found for model '" + model_name +
                                 "' (checkpoint: " + model_info.checkpoint() + ")");
    }

    // The lookup table, the tokenizer and the optional vision tower sit beside
    // the checkpoint in the same snapshot.
    const fs::path bundle = fs::path(checkpoint).parent_path();
    const std::string table_name = model_info.extra<std::string>("halogen_lookup_table", "");
    if (table_name.empty()) {
        throw std::runtime_error("halogen: model '" + model_name +
                                 "' names no halogen_lookup_table");
    }
    const std::string lookup_table = (bundle / table_name).string();
    const std::string tokenizer = (bundle / kTokenizerDir).string();
    const std::string vision_name = model_info.extra<std::string>("halogen_vision_tower", "");
    const std::string vision = vision_name.empty() ? "" : (bundle / vision_name).string();
    for (const auto& required : {lookup_table, tokenizer, vision}) {
        if (!required.empty() && !fs::exists(required)) {
            throw std::runtime_error("halogen: the bundle for '" + model_name + "' is missing " +
                                     required);
        }
    }

    const json ctx_option = options.get_option("ctx_size");
    const int ctx_size = ctx_option.is_number_integer() && ctx_option.get<int>() > 0
                             ? ctx_option.get<int>()
                             : kNativeContext;

    device_type_ = DEVICE_GPU;
    port_ = choose_port();

    ServerCommand command;
    command.model_files = {checkpoint, lookup_table, tokenizer, vision};
    command.env = {
        {"HALOGEN_CHECKPOINT", checkpoint},
        {"HALOGEN_NGRAM_TABLE", lookup_table},
        {"HALOGEN_TOKENIZER", tokenizer},
    };
    if (!vision.empty()) {
        command.env.push_back({"HALOGEN_VISION_TOWER", vision});
    }
    command.env.insert(command.env.end(), {
        {"HALOGEN_API_PORT", std::to_string(port_)},
        {"HALOGEN_CTX", std::to_string(ctx_size)},
    });
    command.port = port_;
    command.ready_endpoint = "/health";

    LOG(INFO, "Halogen") << "Starting " << model_name << " on port " << port_ << std::endl;
    const bool inherit_output = (log_level_ == "info") || is_debug();
    start_server(std::make_unique<ContainerProcess>(
                     ProcessOutput{inherit_output, true}, halogen::descriptor.recipe, kBackend,
                     model_name, *halogen::descriptor.container_for(kBackend),
                     BackendUtils::get_backend_image(halogen::descriptor.recipe, kBackend)),
                 command,
                 (std::max)(kStartupTimeoutSeconds, utils::HttpClient::get_default_timeout()));
}

void WrappedServer::forward_streaming_request(const std::string& endpoint,
                                              const std::string& request_body,
                                              httplib::DataSink& sink,
                                              bool sse,
                                              long timeout_seconds,
                                              TelemetryCallback telemetry_callback) {
    if (!is_backend_alive()) {
        if (was_watchdog_triggered() || has_backend_process_exited()) {
            if (!was_watchdog_triggered()) {
                request_backend_reset_from_watchdog("backend process exited before streaming request");
            }
            throw BackendStreamRetryableReset(get_watchdog_reset_reason());
        }

        json error = ErrorResponse::from_exception(ModelNotLoadedException(server_name_));
        std::string error_msg = "data: " + error.dump() + "\n\n";
        sink.write(error_msg.c_str(), error_msg.size());
        sink.done();
        return;
    }

    BackendRequestScope request_scope(*this, BackendRequestKind::Streaming);

    std::string url = get_base_url() + endpoint;
    bool streamed_any_bytes = false;
    auto mark_stream_progress = [this, &streamed_any_bytes]() {
        if (!streamed_any_bytes) {
            set_streaming(true);
        }
        streamed_any_bytes = true;
        note_backend_activity();
    };

    try {
        if (sse) {
            // Use StreamingProxy to forward the SSE stream with telemetry callback
            // Use INFERENCE_TIMEOUT_SECONDS (0 = infinite) as chat completions can take a long time
            StreamingProxy::forward_sse_stream(url, request_body, sink,
                [telemetry_callback](const StreamingProxy::TelemetryData& telemetry) {
                    if (telemetry_callback) {
                        telemetry_callback(telemetry);
                    }
                },
                timeout_seconds,
                mark_stream_progress
            );
        } else {
            StreamingProxy::forward_byte_stream(url, request_body, sink, timeout_seconds,
                mark_stream_progress
            );
        }
    } catch (const std::exception& e) {
        // Log the error but don't crash the server
        LOG(ERROR, "WrappedServer") << "Streaming request failed: " << e.what() << std::endl;

        bool will_retry = (was_watchdog_triggered() || has_backend_process_exited() ||
                           is_backend_connection_failure(e.what()) ||
                           is_gpu_hang_or_compute_error(e.what())) && !streamed_any_bytes;

        if (telemetry_callback && !will_retry) {
            StreamingProxy::TelemetryData error_telemetry;
            error_telemetry.error_message = e.what();
            telemetry_callback(error_telemetry);
        }

        // Try to send error to client if possible
        try {
            json error;
            if (was_watchdog_triggered() || has_backend_process_exited() ||
                is_backend_connection_failure(e.what()) ||
                is_gpu_hang_or_compute_error(e.what())) {
                if (!was_watchdog_triggered()) {
                    const std::string reset_reason = has_backend_process_exited()
                        ? "backend process exited during streaming request"
                        : (is_gpu_hang_or_compute_error(e.what())
                            ? "gpu hang or compute error during streaming request"
                            : "backend connection failed during streaming request: " + std::string(e.what()));
                    request_backend_reset_from_watchdog(reset_reason);
                }

                // If the backend died before the client received any stream bytes,
                // let the router reload and replay the streaming request once. Once
                // bytes have reached the client, replaying could duplicate tokens or
                // corrupt the SSE protocol, so we only reload for the next request.
                if (!streamed_any_bytes) {
                    throw BackendStreamRetryableReset(get_watchdog_reset_reason());
                }

                error = create_watchdog_reset_response();
            } else {
                error = ErrorResponse::create(std::string(e.what()), "streaming_error");
            }
            std::string error_msg = "data: " + error.dump() + "\n\n";
            sink.write(error_msg.c_str(), error_msg.size());
            sink.done();
        } catch (const BackendStreamRetryableReset&) {
            throw;
        } catch (...) {
            // Sink might be closed, ignore
        }
    }
}
